import{_ as e,o as a,c as i,ag as l}from"./chunks/framework.BpFM782D.js";const u=JSON.parse('{"title":"feature-kickoff","description":"","frontmatter":{},"headers":[],"relativePath":"skills/feature-kickoff.md","filePath":"skills/feature-kickoff.md","lastUpdated":null}'),s={name:"skills/feature-kickoff.md"};function r(n,t,d,o,h,c){return a(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="feature-kickoff" tabindex="-1">feature-kickoff <a class="header-anchor" href="#feature-kickoff" aria-label="Permalink to &quot;feature-kickoff&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>feature-kickoff</td></tr><tr><td>說明</td><td>功能開發啟動流程。自動偵測功能規模（Light/Standard/Full），選擇對應深度的啟動流程。 當用戶說「開始新功能」「實作 XX」「開發 feature-X」「建立新分支開發」 「做一個新功能」「新需求要開工了」「start feature」「這個功能要開始做了」 「來做這個」「開工了」「動工」「implement this」「我要開始寫 XX」時觸發。 即使用戶沒明確說「新功能」，只要是涉及多檔案、多步驟的功能實作也適用。 涉及 bug fix 的單一修改不需要此流程。 依規模執行：讀取 blueprint → 建立 worktree → 拆解任務 → 管理規格。 完成開發後自動銜接 quality-gate → git-workflow → doc-consistency。</td></tr><tr><td></td><td></td></tr><tr><td>來源目錄</td><td><code>skills/feature-kickoff/</code></td></tr></tbody></table><hr><h1 id="feature-kickoff-1" tabindex="-1">Feature Kickoff <a class="header-anchor" href="#feature-kickoff-1" aria-label="Permalink to &quot;Feature Kickoff&quot;">​</a></h1><p>功能開發啟動流程。根據功能規模智慧選擇啟動深度，避免小功能走重流程、大功能漏步驟。</p><h2 id="phase-0-規模分類" tabindex="-1">Phase 0: 規模分類 <a class="header-anchor" href="#phase-0-規模分類" aria-label="Permalink to &quot;Phase 0: 規模分類&quot;">​</a></h2><p>收到功能需求時，先判斷規模。這一步很重要——不同規模的功能需要不同深度的準備工作。 小功能花太多時間在準備上是浪費，大功能準備不足會導致返工。</p><table tabindex="0"><thead><tr><th>級別</th><th>判斷標準</th><th>範例</th></tr></thead><tbody><tr><td><strong>Light</strong></td><td>單一元件/檔案、邏輯清晰、&lt; 2hr</td><td>調整按鈕樣式、修改文案、新增一個靜態頁面</td></tr><tr><td><strong>Standard</strong></td><td>2-5 個檔案、涉及既有模式、半天~1天</td><td>新增一個列表頁、串接新 API、重構元件</td></tr><tr><td><strong>Full</strong></td><td>跨模組、需要架構決策、&gt; 1天</td><td>新增完整功能模組、重大重構、新增認證流程</td></tr></tbody></table><p>如果不確定規模，偏向選擇高一級——準備過頭比準備不足好。</p><h3 id="各級別執行步驟" tabindex="-1">各級別執行步驟 <a class="header-anchor" href="#各級別執行步驟" aria-label="Permalink to &quot;各級別執行步驟&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步驟</th><th style="text-align:center;">Light</th><th style="text-align:center;">Standard</th><th style="text-align:center;">Full</th></tr></thead><tbody><tr><td>Phase 1: 讀取設計規範</td><td style="text-align:center;">快速掃描</td><td style="text-align:center;">重點閱讀</td><td style="text-align:center;">完整閱讀</td></tr><tr><td>Phase 2: 建立 Worktree</td><td style="text-align:center;">跳過</td><td style="text-align:center;">建議</td><td style="text-align:center;">必要</td></tr><tr><td>Phase 3: 拆解任務</td><td style="text-align:center;">心智清單</td><td style="text-align:center;">結構化清單</td><td style="text-align:center;">委託 requirement-analyzer</td></tr><tr><td>Phase 4: 規格管理</td><td style="text-align:center;">跳過</td><td style="text-align:center;">視情況</td><td style="text-align:center;">OpenSpec</td></tr></tbody></table><hr><h2 id="phase-1-讀取設計規範" tabindex="-1">Phase 1: 讀取設計規範 <a class="header-anchor" href="#phase-1-讀取設計規範" aria-label="Permalink to &quot;Phase 1: 讀取設計規範&quot;">​</a></h2><p>在寫程式碼前，先了解設計意圖。讀什麼、讀多深取決於規模和功能類型。</p><h3 id="light-快速掃描" tabindex="-1">Light: 快速掃描 <a class="header-anchor" href="#light-快速掃描" aria-label="Permalink to &quot;Light: 快速掃描&quot;">​</a></h3><p>只讀與修改直接相關的檔案：</p><ul><li>該元件的 blueprint 規格（如果有）</li><li><code>docs/DESIGN_GUIDELINE.md</code> 的相關章節</li></ul><h3 id="standard-重點閱讀" tabindex="-1">Standard: 重點閱讀 <a class="header-anchor" href="#standard-重點閱讀" aria-label="Permalink to &quot;Standard: 重點閱讀&quot;">​</a></h3><p>根據功能類型選讀：</p><table tabindex="0"><thead><tr><th>功能類型</th><th>優先閱讀</th></tr></thead><tbody><tr><td>新頁面</td><td><code>information-architecture/routes.md</code> → <code>navigation.md</code> → 相關 <code>design-system/components/</code></td></tr><tr><td>API 串接</td><td><code>standards/api-integration.md</code> → <code>standards/content-model-api-db-spec.md</code></td></tr><tr><td>UI 元件</td><td><code>design-system/tokens/design-tokens.md</code> → <code>design-system/components/frontstage/</code></td></tr><tr><td>內容變更</td><td><code>content/pages/</code> 相關目錄 → <code>information-architecture/page-inventory.md</code></td></tr></tbody></table><h3 id="full-完整閱讀" tabindex="-1">Full: 完整閱讀 <a class="header-anchor" href="#full-完整閱讀" aria-label="Permalink to &quot;Full: 完整閱讀&quot;">​</a></h3><p>依序讀取：</p><ol><li><code>blueprint/architecture/overview.md</code> → 技術架構總覽</li><li><code>blueprint/init-plans/frontstage-web.md</code> → 實作計畫（確認 Phase 和 Change 編號）</li><li><code>blueprint/information-architecture/</code> → 路由、導航、使用者流程</li><li><code>blueprint/design-system/</code> → 相關元件規範和 tokens</li><li><code>blueprint/standards/</code> → 相關標準文件</li></ol><p><strong>目的</strong>：確保實作與設計規範一致，避免返工。 如果專案沒有 <code>blueprint/</code> 目錄，讀取 <code>README.md</code>、<code>CLAUDE.md</code> 或其他架構文件替代。</p><hr><h2 id="phase-2-建立-worktree-隔離開發" tabindex="-1">Phase 2: 建立 Worktree 隔離開發 <a class="header-anchor" href="#phase-2-建立-worktree-隔離開發" aria-label="Permalink to &quot;Phase 2: 建立 Worktree 隔離開發&quot;">​</a></h2><p>Worktree 讓你在獨立目錄開發新功能，不影響主分支的工作狀態。 這對同時處理多個功能、或需要長時間開發的功能特別有用。</p><h3 id="何時需要" tabindex="-1">何時需要 <a class="header-anchor" href="#何時需要" aria-label="Permalink to &quot;何時需要&quot;">​</a></h3><ul><li><strong>Light</strong>: 跳過——直接在當前分支工作即可</li><li><strong>Standard</strong>: 建議——如果預期 &gt; 3 個 commits</li><li><strong>Full</strong>: 必要——隔離大型功能開發</li></ul><h3 id="如何建立" tabindex="-1">如何建立 <a class="header-anchor" href="#如何建立" aria-label="Permalink to &quot;如何建立&quot;">​</a></h3><p>使用 Claude Code 的 <code>EnterWorktree</code> 工具（輸入 &quot;worktree&quot; 觸發）。分支會自動命名。</p><p>如果 <code>EnterWorktree</code> 不可用，手動建立：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> worktree</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .worktrees/feature-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h3 id="規則" tabindex="-1">規則 <a class="header-anchor" href="#規則" aria-label="Permalink to &quot;規則&quot;">​</a></h3><ul><li>所有檔案操作使用 worktree 完整路徑</li><li>完成後合併回主分支，再清理 worktree</li></ul><hr><h2 id="phase-3-拆解任務" tabindex="-1">Phase 3: 拆解任務 <a class="header-anchor" href="#phase-3-拆解任務" aria-label="Permalink to &quot;Phase 3: 拆解任務&quot;">​</a></h2><p>不同規模用不同深度的拆解方式。</p><h3 id="light-心智清單" tabindex="-1">Light: 心智清單 <a class="header-anchor" href="#light-心智清單" aria-label="Permalink to &quot;Light: 心智清單&quot;">​</a></h3><p>直接在回應中列出 2-5 個步驟，不需要正式文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>要做的事：</span></span>
<span class="line"><span>1. 修改 XXX 元件的樣式</span></span>
<span class="line"><span>2. 確認 RWD 表現</span></span>
<span class="line"><span>3. 跑 lint 確認</span></span></code></pre></div><h3 id="standard-結構化清單" tabindex="-1">Standard: 結構化清單 <a class="header-anchor" href="#standard-結構化清單" aria-label="Permalink to &quot;Standard: 結構化清單&quot;">​</a></h3><p>用 TaskCreate 工具建立任務清單（如不可用，用 markdown checklist）：</p><p>每個任務需包含：</p><ul><li><strong>subject</strong>: 做什麼（祈使句，如「建立 NewsCard 元件」）</li><li><strong>description</strong>: 完成標準和技術細節</li><li><strong>activeForm</strong>: 進行式描述（如「建立 NewsCard 元件中」）</li><li>標示任務間依賴關係（<code>blockedBy</code>）</li></ul><p><strong>節奏</strong>：建立全部任務 → 按序標記 in_progress → 完成 → 標記 completed → 下一個</p><h3 id="full-委託-requirement-analyzer-不要自己拆解" tabindex="-1">Full: 委託 requirement-analyzer（不要自己拆解） <a class="header-anchor" href="#full-委託-requirement-analyzer-不要自己拆解" aria-label="Permalink to &quot;Full: 委託 requirement-analyzer（不要自己拆解）&quot;">​</a></h3><p>Full 級別的需求拆解<strong>必須委託</strong> <code>requirement-analyzer</code> 技能處理。 這不是建議，而是流程要求。原因如下：</p><ul><li><code>requirement-analyzer</code> 會做<strong>多輪對話式需求釐清</strong>（Phase 1），挖掘你自己可能遺漏的邊界情境</li><li>它有系統性的 <strong>Edge Cases 掃描</strong>（6 個維度：輸入、狀態、權限、網路、裝置、資料），比你手動列舉更全面</li><li>它產出的功能拆解包含<strong>優先級（P0/P1/P2）和工時估算</strong>，feature-kickoff 不做這些</li></ul><p>即使你已經對功能有充分理解，仍然要委託——因為 requirement-analyzer 的價值在於<strong>結構化的檢查流程</strong>，不是知識補充。</p><p><strong>委託方式：</strong></p><p>告訴用戶你需要先做需求分析，然後呼叫 requirement-analyzer 技能：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我會先用 requirement-analyzer 做完整的需求分析和任務拆解。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/requirement-analyzer</span></span></code></pre></div><p>requirement-analyzer 產出後，再用 TaskCreate 將功能點（FE-001、FE-002...）轉為可追蹤的任務。</p><hr><h2 id="phase-4-規格管理-僅-full-級別" tabindex="-1">Phase 4: 規格管理（僅 Full 級別） <a class="header-anchor" href="#phase-4-規格管理-僅-full-級別" aria-label="Permalink to &quot;Phase 4: 規格管理（僅 Full 級別）&quot;">​</a></h2><p>大型功能如果涉及架構決策或規格變更，用 OpenSpec 追蹤：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/opsx:new         → 建立新的 change（含 proposal）</span></span>
<span class="line"><span>/opsx:continue    → 逐步建立 artifacts（design → specs → tasks）</span></span>
<span class="line"><span>/opsx:apply       → 按 tasks 執行實作</span></span>
<span class="line"><span>/opsx:verify      → 驗證實作符合規格</span></span>
<span class="line"><span>/opsx:archive     → 完成後歸檔</span></span></code></pre></div><p><strong>判斷標準</strong>：如果功能不涉及規格或架構變更，跳過此步驟。 簡單的功能開發不需要 OpenSpec——它是為需要留下決策紀錄的重大變更設計的。</p><hr><h2 id="完成檢查" tabindex="-1">完成檢查 <a class="header-anchor" href="#完成檢查" aria-label="Permalink to &quot;完成檢查&quot;">​</a></h2><p>根據級別確認：</p><h3 id="light" tabindex="-1">Light <a class="header-anchor" href="#light" aria-label="Permalink to &quot;Light&quot;">​</a></h3><ul><li>[ ] 已了解修改範圍</li><li>[ ] 程式碼完成</li><li>→ 銜接 <code>quality-gate</code>：跑 <code>npm run lint</code> 和相關測試即可</li></ul><h3 id="standard" tabindex="-1">Standard <a class="header-anchor" href="#standard" aria-label="Permalink to &quot;Standard&quot;">​</a></h3><ul><li>[ ] 已讀取相關 blueprint 或架構文件</li><li>[ ] 任務已拆解並追蹤</li><li>[ ] Worktree 已建立（如適用）</li><li>→ 銜接 <code>quality-gate</code>：完整品質閘門（build + types + lint + test）</li><li>→ 銜接 <code>git-workflow</code>：按任務顆粒度 commit，完成後建 PR</li></ul><h3 id="full" tabindex="-1">Full <a class="header-anchor" href="#full" aria-label="Permalink to &quot;Full&quot;">​</a></h3><ul><li>[ ] 已完整讀取 blueprint 相關章節</li><li>[ ] Worktree 已建立</li><li>[ ] 需求已委託 <code>requirement-analyzer</code> 完整分析（不是自己拆解）</li><li>[ ] requirement-analyzer 產出已轉為 TaskCreate 任務</li><li>[ ] 規格變更已用 OpenSpec 追蹤（如適用）</li><li>[ ] 所有任務已完成並標記 completed</li><li>→ <strong>銜接 <code>quality-gate</code></strong>：全套檢查（build + types + lint + test + security）</li><li>→ <strong>銜接 <code>git-workflow</code></strong>：階段性 commit + PR</li><li>→ <strong>銜接 <code>doc-consistency</code></strong>：修改了 blueprint、IA、或架構文件時必須觸發，確保關聯文件同步</li></ul><hr><h2 id="技能銜接總覽" tabindex="-1">技能銜接總覽 <a class="header-anchor" href="#技能銜接總覽" aria-label="Permalink to &quot;技能銜接總覽&quot;">​</a></h2><p>以下技能在 feature-kickoff 流程中會被用到，依時間順序：</p><table tabindex="0"><thead><tr><th>時機</th><th>技能</th><th>觸發條件</th></tr></thead><tbody><tr><td>Phase 3 (Full)</td><td><code>requirement-analyzer</code></td><td>Full 級別必須委託需求分析</td></tr><tr><td>Phase 4 (Full)</td><td><code>opsx:new</code> / <code>opsx:continue</code></td><td>涉及規格或架構變更時</td></tr><tr><td>完成後</td><td><code>quality-gate</code></td><td>所有級別，跑品質閘門</td></tr><tr><td>commit 時</td><td><code>git-workflow</code></td><td>Standard/Full，按顆粒度 commit</td></tr><tr><td>改文件時</td><td><code>doc-consistency</code></td><td>修改了 blueprint/IA/架構文件</td></tr></tbody></table><h2 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to &quot;注意事項&quot;">​</a></h2><ul><li>Commit message 使用 conventional commit 前綴 + 繁體中文描述</li><li>完成重要階段使用 <code>checkpoint:</code> 前綴提交</li><li>修改 information-architecture 文件時，<code>doc-consistency</code> 會自動觸發同步檢查</li></ul>`,74)])])}const k=e(s,[["render",r]]);export{u as __pageData,k as default};
